function GlassPipeShearsMaker.init() GlassPipeShearsMaker.ironStock=18; GlassPipeShearsMaker.bronzeStock=14; GlassPipeShearsMaker.woodStock=10; GlassPipeShearsMaker.leatherStock=8; GlassPipeShearsMaker.silverStock=8; GlassPipeShearsMaker.goldStock=6; GlassPipeShearsMaker.jewelStock=4; GlassPipeShearsMaker.pearlStock=4; GlassPipeShearsMaker.productStock={}; GlassPipeShearsMaker.buildings={}; GlassPipeShearsMaker.maker=nil; GlassPipeShearsMaker.activeMaking={}; GlassPipeShearsMaker.totalProducts=0; GlassPipeShearsMaker.dayTimer=0; print("[GlassPipeShearsMaker] Royal Glass Pipe Shears Maker System initialized (6 products, 4 buildings)") end
function GlassPipeShearsMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassPipeShearsMaker.maker={name=n or ("Škardar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Škardar najet: %s (spretnost: %d)",GlassPipeShearsMaker.maker.name,s),"success") end; return true end
function GlassPipeShearsMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassPipeShearsMaker.build(id) local ok,e=GlassPipeShearsMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassPipeShearsMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassPipeShearsMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassPipeShearsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassPipeShearsMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassPipeShearsMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassPipeShearsMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassPipeShearsMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassPipeShearsMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassPipeShearsMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassPipeShearsMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassPipeShearsMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassPipeShearsMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassPipeShearsMaker.buildings==0 then return false,"Potrebna skardna delavnica" end; if not GlassPipeShearsMaker.maker then return false,"Potreben skardar" end; return true end
function GlassPipeShearsMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassPipeShearsMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassPipeShearsMaker.ironStock=GlassPipeShearsMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassPipeShearsMaker.bronzeStock=GlassPipeShearsMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassPipeShearsMaker.woodStock=GlassPipeShearsMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassPipeShearsMaker.leatherStock=GlassPipeShearsMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassPipeShearsMaker.silverStock=GlassPipeShearsMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassPipeShearsMaker.goldStock=GlassPipeShearsMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassPipeShearsMaker.jewelStock=GlassPipeShearsMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassPipeShearsMaker.pearlStock=GlassPipeShearsMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassPipeShearsMaker.maker then t=math.max(1,t-math.floor(GlassPipeShearsMaker.maker.skill/13)) end; table.insert(GlassPipeShearsMaker.activeMaking,{id="glasspipeshears_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassPipeShearsMaker.completeMaking(m) local q=1.0+(GlassPipeShearsMaker.getQualityBonus()/100); if GlassPipeShearsMaker.maker then q=q+(GlassPipeShearsMaker.maker.skill/140) end; q=math.min(2.5,q); GlassPipeShearsMaker.productStock[m.productType]=(GlassPipeShearsMaker.productStock[m.productType] or 0)+m.quantity; GlassPipeShearsMaker.totalProducts=GlassPipeShearsMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassPipeShearsMaker.maker then GlassPipeShearsMaker.maker.itemsMade=GlassPipeShearsMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassPipeShearsMaker.maker.skill=math.min(100,GlassPipeShearsMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Škarde izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasspipeshears.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassPipeShearsMaker.update(dt) if not _G.state then return end; GlassPipeShearsMaker.dayTimer=GlassPipeShearsMaker.dayTimer+dt; if GlassPipeShearsMaker.dayTimer>=30 then GlassPipeShearsMaker.dayTimer=0; for i=#GlassPipeShearsMaker.activeMaking,1,-1 do local m=GlassPipeShearsMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassPipeShearsMaker.completeMaking(m); table.remove(GlassPipeShearsMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassPipeShearsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassPipeShearsMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassPipeShearsMaker.getStats() return {ironStock=GlassPipeShearsMaker.ironStock,bronzeStock=GlassPipeShearsMaker.bronzeStock,woodStock=GlassPipeShearsMaker.woodStock,leatherStock=GlassPipeShearsMaker.leatherStock,silverStock=GlassPipeShearsMaker.silverStock,goldStock=GlassPipeShearsMaker.goldStock,jewelStock=GlassPipeShearsMaker.jewelStock,pearlStock=GlassPipeShearsMaker.pearlStock,productStock=GlassPipeShearsMaker.productStock,numBuildings=#GlassPipeShearsMaker.buildings,hasMaker=GlassPipeShearsMaker.maker~=nil,makerName=GlassPipeShearsMaker.maker and GlassPipeShearsMaker.maker.name or "—",makerSkill=GlassPipeShearsMaker.maker and GlassPipeShearsMaker.maker.skill or 0,activeMaking=#GlassPipeShearsMaker.activeMaking,totalProducts=GlassPipeShearsMaker.totalProducts} end
